            return CheckResult(f"template_part{n}", False, f"{path.name} missing or empty",
                               relay=f"output/{path.name} 不存在或为空。")
        if n == 1 and "# --- END METADATA ---" not in path.read_text(encoding="utf-8", errors="replace"):
